-- Fase 9: indicadores de decisión y alertas dirigidas de Recursos Humanos.
create or replace function public.list_hr_decision_indicators(p_token text,p_year integer,p_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare v_user public.app_users;v_start date:=make_date(p_year,p_month,1);v_previous date:=(make_date(p_year,p_month,1)-interval '1 month')::date;
begin
 v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not(coalesce((v_user.permissions->>'ver_indicadores_rrhh')::boolean,false) or coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false))) then return jsonb_build_object('success',false,'error','No posee permiso para consultar indicadores y alertas de Recursos Humanos.');end if;

 -- Alertas personales del usuario conectado, respetando su alcance jerárquico.
 insert into public.app_notifications(user_id,notification_type,severity,event_key,title,message,action_section)
 select v_user.id,'RRHH','high','RRHH:PERMISOS:'||e.id||':'||p_year,'Permisos recurrentes',e.full_name||' registra '||count(*)||' permisos o licencias durante '||p_year||'.','Indicadores Operativos RRHH'
 from public.hr_employee_cases c join public.hr_employees e on e.id=c.employee_id where c.case_type='PERMISO' and extract(year from c.start_date)=p_year and c.status not in('RECHAZADO','ANULADA') and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)) group by e.id,e.full_name having count(*)>=3
 on conflict(user_id,event_key) where event_key is not null do update set message=excluded.message,severity=excluded.severity,created_at=now(),read_at=null;
 insert into public.app_notifications(user_id,notification_type,severity,event_key,title,message,action_section)
 select v_user.id,'RRHH','critical','RRHH:DISCIPLINA:'||e.id||':'||p_year,'Reincidencia disciplinaria',e.full_name||' acumula '||count(*)||' amonestaciones durante '||p_year||'.','Indicadores Operativos RRHH'
 from public.hr_employee_cases c join public.hr_employees e on e.id=c.employee_id where c.case_type='AMONESTACION' and extract(year from c.start_date)=p_year and c.status<>'ANULADA' and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)) group by e.id,e.full_name having count(*)>=2
 on conflict(user_id,event_key) where event_key is not null do update set message=excluded.message,severity=excluded.severity,created_at=now(),read_at=null;

 return jsonb_build_object('success',true,
 'payroll_variation',(with c as(select coalesce(sum(l.gross_salary),0) gross,coalesce(sum(l.net_amount),0) net,count(distinct l.employee_id) employees from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month and b.status<>'BORRADOR'),p as(select coalesce(sum(l.gross_salary),0) gross,coalesce(sum(l.net_amount),0) net,count(distinct l.employee_id) employees from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=extract(year from v_previous)::integer and b.payroll_month=extract(month from v_previous)::integer and b.status<>'BORRADOR') select jsonb_build_object('current_gross',c.gross,'previous_gross',p.gross,'gross_change',c.gross-p.gross,'gross_change_rate',round(100.0*(c.gross-p.gross)/nullif(p.gross,0),2),'current_net',c.net,'previous_net',p.net,'employee_change',c.employees-p.employees) from c cross join p),
 'benefits_by_unit',coalesce((select jsonb_agg(to_jsonb(x) order by x.total desc,x.direction_name) from(select coalesce(nullif(e.direction_name,''),'Sin dirección') direction_name,b.payroll_type,count(distinct l.employee_id) employees,sum(l.gross_salary) total from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id join public.hr_employees e on e.id=l.employee_id where b.payroll_year=p_year and b.payroll_month=p_month and b.payroll_type in('PRIMA_TRANSPORTE','VIATICOS','HORAS_EXTRAS') group by e.direction_name,b.payroll_type)x),'[]'::jsonb),
 'consecutive_licenses',coalesce((select jsonb_agg(to_jsonb(x) order by x.license_count desc,x.full_name) from(select e.id employee_id,e.employee_code,e.full_name,e.position_name,e.direction_name,count(*) license_count,sum(c.day_count) total_days,min(c.start_date) first_date,max(c.end_date) last_date from public.hr_employee_cases c join public.hr_employees e on e.id=c.employee_id where c.case_type='PERMISO' and (lower(c.category) like '%licencia%' or lower(c.reason) like '%licencia%') and extract(year from c.start_date)=p_year and c.status not in('RECHAZADO','ANULADA') and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)) group by e.id having count(*)>=2 and max(c.start_date)-min(c.end_date)<=31)x),'[]'::jsonb),
 'directed_alerts',coalesce((select jsonb_agg(to_jsonb(x) order by x.severity,x.created_at desc) from(select id,title,message,severity,action_section,created_at from public.app_notifications where user_id=v_user.id and notification_type='RRHH' and read_at is null)x),'[]'::jsonb));
end $$;
grant execute on function public.list_hr_decision_indicators(text,integer,integer) to anon,authenticated;
